<template><div><UsabilityView v-if="usabilityEnabled"/><Card v-else><h2>二级商户与渠道关系</h2><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><Input v-model="targetStore" placeholder="店铺编号（可选）" style="width:230px"/><Button @click="page=1;reload()">查询</Button><Button type="primary" :disabled="pending||uploadsPending" @click="create(null)">新增关联</Button></div><Table :data="records" :columns="columns" :loading="loading" no-data-text="暂无关联"><template slot="state" slot-scope="{row}">{{label(row.mode)}} / {{label(row.applicationState)}}<br/>{{label(row.capabilityState)}} · {{row.enabled?'启用':'停用'}}</template><template slot="action" slot-scope="{row}"><Button size="small" @click="detail(row)">详情与操作</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" title="建立二级商户关联" width="760" :mask-closable="false" :closable="!uploadsPending"><FieldsForm v-model="form" :fields="fields" :disabled="busy||pending||uploadsPending"/><Button type="primary" :disabled="pending||uploadsPending" :loading="busy" @click="save">保存未核验关联</Button></Drawer><Drawer v-model="detailShow" title="进件状态与操作历史" width="90"><template v-if="selected"><div class="s1-toolbar"><Button v-if="['DRAFT','NEED_CORRECTION'].includes(selected.relation.applicationState)" :disabled="pending||busy||uploadsPending" @click="editMaterials">编辑材料</Button><Button v-if="['DRAFT','NEED_CORRECTION'].includes(selected.relation.applicationState)" type="primary" :disabled="pending||busy||uploadsPending" @click="command('submit')">提交当前材料版本</Button><Button v-else :disabled="pending||busy||uploadsPending" @click="command('query')">按原申请编号回查</Button><Button :disabled="pending||busy||uploadsPending" @click="command(selected.relation.enabled?'disable':'enable')">{{selected.relation.enabled?'停用关联':'启用关联'}}</Button><Button :disabled="pending||busy||uploadsPending" @click="create(selected.relation)">创建替换关系</Button><Button v-if="can('channel.receiver')" :disabled="pending||busy||uploadsPending" @click="receiverForm={receiverId:selected.relation.receiverId,reason:''};receiverShow=true">关联平台接收方</Button></div><Button v-if="selected.relation.requiredActions&&['LEGAL_VERIFICATION','ADMIN_SIGNING'].includes(selected.relation.requiredActions.action)" :disabled="busy||pending||uploadsPending" @click="showRequiredAction">查看受控渠道待办</Button><Alert v-if="channelAction" show-icon><p>{{channelAction.instruction}}</p><p>展示有效期：{{channelAction.displayUntil}}</p><a v-if="channelAction.url" :href="channelAction.url" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">由指定当事人打开微信渠道入口</a><Button size="small" @click="clearChannelAction">隐藏待办</Button></Alert><RecordDetail :value="{relation:selected.relation,materialRevisions:selected.materialRevisions,operations:selected.operations}"/></template></Drawer><Drawer v-model="materialShow" title="进件材料" width="900" :mask-closable="false" :closable="!uploadsPending"><ChannelMaterialEditor v-if="materialShow&&selected" :key="selected.relation.id+':'+selected.relation.version" :value="selected.materials.fields" :receipt-scope="selected.relation.id" :protected-fields="selected.materials.protectedFields" :licenses="licenses" :disabled="busy||pending||uploadsPending" @save="saveMaterials" @preview="preview"/></Drawer><Drawer v-model="receiverShow" title="关联平台接收方" width="700" :mask-closable="false" :closable="!uploadsPending"><FieldsForm v-model="receiverForm" :fields="[{key:'receiverId',label:'平台接收关系编号',max:19,help:'必须是同配置、同模式的有效平台接收关系；留空解除。'},{key:'reason',label:'原因',type:'textarea',required:true,max:500}]" :disabled="busy||pending||uploadsPending"/><Button type="primary" :loading="busy" :disabled="pending||uploadsPending" @click="saveReceiver">保存关联</Button></Drawer></Card></div></template>
<script>import {usabilityEntry} from './usability/enabled';import {leaveGuard} from './usability/entry';import UiView from './usability/Submerchants';import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import FieldsForm from './FieldsForm';import RecordDetail from './RecordDetail';import ChannelMaterialEditor from './ChannelMaterialEditor';const LegacyView = {mixins:[pageMixin],components:{StatusPanel,FieldsForm,RecordDetail,ChannelMaterialEditor},data:()=>({channelAction:null,channelActionTimer:null,targetStore:'',show:false,detailShow:false,materialShow:false,receiverShow:false,form:{},receiverForm:{},licenses:[],fields:[{key:'storeId',label:'店铺编号',required:true,max:19},{key:'configId',label:'渠道配置编号',required:true,max:19},{key:'predecessorId',label:'被替换关系编号',max:19},{key:'existingSubMchid',label:'已有二级商户号',max:64,help:'选填；手工关联保持待核验，不直接取得真实资格。'},{key:'reason',label:'关联原因',type:'textarea',required:true,max:500}],columns:[{title:'店铺编号',key:'storeId',minWidth:180},{title:'关联编号',key:'id',minWidth:180},{title:'二级商户号',key:'subMchidMasked'},{title:'业务申请编号',key:'outRequestNo',minWidth:210},{title:'状态',slot:'state',minWidth:210},{title:'版本',key:'version',width:80},{title:'操作',slot:'action',width:140}]}),mounted(){if(this.usabilityEnabled)return;const id=this.$route.query.targetStore;if(typeof id==='string'&&/^\d{1,19}$/.test(id))this.targetStore=id;this.reload();},beforeDestroy(){this.clearChannelAction();},watch:{detailShow(value){if(!value)this.clearChannelAction();}},methods:{clearChannelAction(){clearTimeout(this.channelActionTimer);this.channelAction=null;},async showRequiredAction(){this.clearChannelAction();try{const row=this.selected.relation,value=await s1Read('/submerchants/'+row.id+'/required-action',{expectedVersion:row.version});if(!this.detailShow||!this.selected||this.selected.relation.id!==row.id)return;const remaining=Date.parse(value.displayUntil)-Date.now();if(remaining<=0)throw Error('渠道待办已过期，请先回查原申请。');this.channelAction=value;this.channelActionTimer=setTimeout(()=>this.clearChannelAction(),Math.min(remaining,300000));}catch(e){this.error=e.message;}},reload(){return this.load('/submerchants',{targetStore:this.targetStore||undefined});},create(previous){this.form={storeId:previous?previous.storeId:this.targetStore,configId:previous?previous.configId:'',...(previous?{predecessorId:previous.id}:{}),reason:''};this.show=true;},async save(){const body={...this.form};['predecessorId','existingSubMchid'].forEach(k=>{if(!body[k])delete body[k];});try{await this.run('/submerchants',body);this.show=false;await this.reload();}catch(_){}},async detail(row){this.clearChannelAction();try{this.selected=await s1Read('/submerchants/'+row.id);this.detailShow=true;}catch(e){this.error=e.message;}},async command(action){const row=this.selected.relation;const result=await this.reasonAction('/submerchants/'+row.id+'/'+action,{submit:'提交进件资料',query:'查询原业务申请',enable:'启用已核验关联',disable:'停用关联并立即失效资格'}[action],{expectedVersion:row.version});if(result){await this.detail(row);await this.reload();}},async editMaterials(){try{const profile=await s1Read('/stores/'+this.selected.relation.storeId);this.licenses=profile.qualifications.versions.filter(q=>q.type==='BUSINESS_LICENSE'&&['ACTIVE','APPROVED'].includes(q.status)).flatMap(q=>(q.details.fileIds||[]).map(id=>({id,label:'营业执照版本 '+q.revision+' · '+id})));this.materialShow=true;}catch(e){this.error=e.message;}},async saveMaterials(body){const row=this.selected.relation;try{await this.run('/submerchants/'+row.id+'/materials',{expectedVersion:row.version,...body},'PUT');this.materialShow=false;await this.detail(row);await this.reload();}catch(_){}},async saveReceiver(){const row=this.selected.relation;try{await this.run('/submerchants/'+row.id+'/receiver',{expectedVersion:row.version,receiverId:this.receiverForm.receiverId||null,reason:this.receiverForm.reason},'PUT');this.receiverShow=false;await this.detail(row);await this.reload();}catch(_){}}}};LegacyView.mixins.push(usabilityEntry);LegacyView.components={...LegacyView.components,UsabilityView:UiView};LegacyView.beforeRouteLeave=leaveGuard;LegacyView.beforeRouteUpdate=leaveGuard;export default LegacyView;</script><style scoped>.s1-toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.ivu-page{margin-top:18px}</style>
